CREATE TABLE il_t(id int, s text);
CREATE TABLE il_e(id int);
CREATE TABLE il_z(x int, s text);
INSERT INTO il_t VALUES (1,'a'),(2,'b'),(3,NULL);
INSERT INTO il_z VALUES (0,'a'),(NULL,'B');
SELECT * FROM il_t WHERE id > 5 AND id IN (SELECT 1/x FROM il_z);
SELECT * FROM il_t WHERE id > 5 AND id NOT IN (SELECT 1/x FROM il_z);
SELECT * FROM il_t WHERE id > 5 AND id = ANY (SELECT 1/x FROM il_z);
SELECT * FROM il_t WHERE id > 5 AND id > ALL (SELECT 1/x FROM il_z);
SELECT id IN (SELECT 1/x FROM il_z) FROM il_e;
SELECT CASE WHEN id > 10 THEN id IN (SELECT 1/x FROM il_z) END FROM il_t ORDER BY id;
SELECT id IN (SELECT 1/x FROM il_z) FROM il_t;
SELECT 1 IN (SELECT 1/x FROM il_z) FROM il_e;
SELECT * FROM il_e WHERE 1 IN (SELECT 1/x FROM il_z);
SELECT id FROM il_t WHERE id > 5 AND id IN (SELECT 1/x FROM il_z) ORDER BY id;
SELECT id FROM il_t WHERE id > 5 AND id IN (SELECT 1/x FROM il_z) GROUP BY id;
SELECT id, id IN (SELECT x FROM il_z), id NOT IN (SELECT x FROM il_z), id > ANY (SELECT x FROM il_z), id < ALL (SELECT x+5 FROM il_z WHERE x IS NOT NULL) FROM il_t ORDER BY id;
SELECT id, s IN (SELECT s FROM il_z), s NOT IN (SELECT s FROM il_z WHERE s IS NOT NULL) FROM il_t ORDER BY id;
SELECT id, (id, s) IN (SELECT x+1, s FROM il_z) FROM il_t ORDER BY id;
SELECT id FROM il_t WHERE id IN (SELECT x FROM il_z) OR id IN (SELECT x+2 FROM il_z) ORDER BY id;
SELECT id, '1' IN (SELECT x FROM il_z) FROM il_t ORDER BY id;
SELECT id FROM il_t WHERE id IN (SELECT x FROM il_z WHERE false);
SELECT id, NULL::int NOT IN (SELECT x FROM il_z WHERE false) FROM il_t ORDER BY id;
SELECT count(*) FROM il_t WHERE id IN (SELECT g FROM generate_series(1,2) g);
SELECT id FROM il_t WHERE s COLLATE "C" IN (SELECT lower(s) FROM il_z) ORDER BY id;
SELECT id, id IN (SELECT x FROM il_z) FROM il_t GROUP BY id ORDER BY id;
SELECT 'zz' IN (SELECT x FROM il_z) FROM il_e;
SELECT 'zz' = ANY (SELECT x FROM il_z) FROM il_e;
SELECT 'zz' < ALL (SELECT x FROM il_z) FROM il_e;
SELECT ('zz', 1) IN (SELECT x, 1 FROM il_z) FROM il_e;
SELECT 'zz' = (SELECT x FROM il_z) FROM il_e;
SELECT 1 FROM il_e WHERE (SELECT x FROM il_z) = 'zz';
SELECT * FROM il_e WHERE id IN (SELECT s FROM il_z);
SELECT * FROM il_e WHERE 'zz' IN (SELECT x FROM il_z);
BEGIN;
DECLARE il_c CURSOR FOR SELECT id IN (SELECT 1/x FROM il_z) FROM il_e;
FETCH ALL FROM il_c;
COMMIT;
